import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it, vi } from "vitest";
import YAML from "yaml";
import { classifyProject, findSpecs, nameVariants, suggestDependencies } from "../src/discover.js";
import { discoverCommand } from "../src/commands/discover.js";
import { loadConfig } from "../src/config.js";

/** A GitLab group with an orders API (committed spec), a payments API (generated by tsoa), a storefront, a lib, an empty repo. */
const PROJECTS = [
  { id: 1, path: "orders-service", path_with_namespace: "acme/shop/orders-service", default_branch: "main" },
  { id: 2, path: "payments-service", path_with_namespace: "acme/shop/payments-service", default_branch: "main" },
  { id: 3, path: "storefront", path_with_namespace: "acme/shop/storefront", default_branch: "main" },
  { id: 4, path: "shared-utils", path_with_namespace: "acme/shop/shared-utils", default_branch: "main" },
  { id: 5, path: "empty", path_with_namespace: "acme/shop/empty", default_branch: null },
  { id: 6, path: "qa-tests", path_with_namespace: "acme/shop/qa-tests", default_branch: "main" },
];
const TREES: Record<number, string[]> = {
  1: ["package.json", "openapi.yaml", "test/fixtures/openapi.yaml", ".env.example", "src/app.ts"],
  2: ["package.json", "src/controllers/pay.ts", "docker-compose.yml"],
  3: ["package.json", "src/App.tsx", ".env.example"],
  4: ["package.json", "src/index.ts"],
  6: ["package.json"],
};
const FILES: Record<string, string> = {
  "1:package.json": JSON.stringify({ dependencies: { express: "4" }, scripts: { start: "node ." } }),
  "1:.env.example": "PORT=3000\nPAYMENTS_SERVICE_URL=http://payments-service:3000\n# STOREFRONT_URL=commented out\n",
  "2:package.json": JSON.stringify({ dependencies: { express: "4", tsoa: "6" } }),
  "2:docker-compose.yml": "services:\n  payments:\n    environment:\n      - LEDGER_URL=http://ledger\n",
  "3:package.json": JSON.stringify({ dependencies: { react: "18", "react-dom": "18" } }),
  "3:.env.example": "VITE_ORDERS_API=http://orders/api\nVITE_PAYMENTS_SERVICE_BASE_URL=/pay\n",
  "4:package.json": JSON.stringify({ main: "dist/index.js", types: "dist/index.d.ts" }),
};

function gitlab() {
  return vi.fn(async (url: string) => {
    const u = new URL(url);
    const p = decodeURIComponent(u.pathname.replace(/^\/api\/v4/, ""));
    const json = (d: unknown) => new Response(JSON.stringify(d), { status: 200 });
    if (p === "/groups/acme/shop/projects") return json(PROJECTS);
    const tree = p.match(/^\/projects\/(\d+)\/repository\/tree$/);
    if (tree) return json((TREES[Number(tree[1])] ?? []).map((f) => ({ type: "blob", path: f })));
    const raw = p.match(/^\/projects\/(\d+)\/repository\/files\/(.+)\/raw$/);
    if (raw) {
      const body = FILES[`${raw[1]}:${raw[2]}`];
      return body === undefined ? new Response("", { status: 404 }) : new Response(body, { status: 200 });
    }
    return new Response("not found", { status: 404 });
  });
}

describe("discover --gitlab-group", () => {
  afterEach(() => vi.unstubAllGlobals());

  it("classifies projects and finds their specs (not test fixtures)", () => {
    expect(findSpecs(["test/fixtures/openapi.yaml", "docs/api/openapi.yaml", "openapi.json", "package.json"])).toEqual(["openapi.json", "docs/api/openapi.yaml"]);
    expect(classifyProject(["pom.xml"], undefined, { "pom.xml": "<artifactId>spring-boot-starter-web</artifactId><artifactId>springdoc-openapi-starter</artifactId>" })).toMatchObject({ kind: "api", generator: expect.stringContaining("springdoc") });
    expect(classifyProject(["app/src/main/AndroidManifest.xml"], undefined).kind).toBe("mobile");
    expect(classifyProject(["package.json"], { dependencies: { next: "14" } }).kind).toBe("web");
  });

  it("suggests dependencies only where config names another service, with the file and line", () => {
    expect(nameVariants("orders-service").some((re) => re.test("ORDERS_SERVICE_URL=x"))).toBe(true);
    expect(nameVariants("orders-service").some((re) => re.test("ordersService: http://x"))).toBe(true);
    expect(nameVariants("orders-service").some((re) => re.test("the orders page"))).toBe(false); // bare word in prose
    const s = suggestDependencies([
      { name: "a-service", texts: [{ file: ".env.example", text: "X=1\nB_SERVICE_URL=http://b\n" }] },
      { name: "b-service", texts: [{ file: "values.yaml", text: "# a-service is old\n" }] },
    ]);
    expect(s).toEqual([{ from: "a-service", to: "b-service", evidence: ".env.example:2" }]);
  });

  it("drafts service entries for QA to accept, and --apply adds only the new ones", async () => {
    vi.stubGlobal("fetch", gitlab());
    const cwd = fs.mkdtempSync(path.join(os.tmpdir(), "qas-discover-"));
    fs.writeFileSync(
      path.join(cwd, "qa-sentinel.config.yaml"),
      YAML.stringify({
        version: 1,
        mode: "existing",
        project: { name: "shop" },
        tests: { api: { framework: "playwright", runCommand: "x" } },
        ci: { platform: "gitlab", gitlabUrl: "https://gitlab.example", testRepoProject: "acme/shop/qa-tests" },
        workspace: { services: [{ name: "orders", path: "../orders-service", gitlabProject: "acme/shop/orders-service", openapi: "openapi.yaml" }] },
      }),
    );
    const env = { QA_SENTINEL_GITLAB_TOKEN: "t" };
    expect(await discoverCommand({ cwd, group: "acme/shop", env })).toBe(0);
    const draft = fs.readFileSync(path.join(cwd, "qa-services.draft.yaml"), "utf8");
    const parsed = YAML.parse(draft).services;
    expect(parsed.map((x: { name: string }) => x.name)).toEqual(["orders-service", "payments-service", "storefront"]);
    expect(parsed[0]).toMatchObject({ openapi: "openapi.yaml", dependsOn: ["payments-service"] });
    // "orders" alone counts for orders-service only in a URL host or a service-ish key (VITE_ORDERS_API, http://orders).
    expect(parsed[2]).toMatchObject({ kind: "web", dependsOn: ["orders-service", "payments-service"] });
    expect(draft).toContain('already configured as "orders"');
    expect(draft).toContain("spec generated at build time by tsoa");
    expect(draft).toContain("depends on payments-service? (.env.example:2)");
    const md = fs.readFileSync(path.join(cwd, "qa-services.draft.md"), "utf8");
    expect(md).toContain("- acme/shop/shared-utils: library");
    expect(md).toContain("- acme/shop/empty: unknown, empty repository");
    expect(md).not.toContain("qa-tests");

    await discoverCommand({ cwd, group: "acme/shop", env, apply: true });
    const names = loadConfig(cwd).workspace.services.map((s) => s.name);
    expect(names).toEqual(["orders", "payments-service", "storefront"]);
  });
});
